typedef unsigned char u_char;
typedef unsigned short u_short;
typedef unsigned int u_int;

struct nglTexture
{
  u_int TexStreamPos[2];
  u_short Width;
  u_short Height;
  u_int Hash;
  u_char Type;
  u_char TW;
  u_char TH;
  u_char Pad;
  u_int Flags;
  void* ph;
  u_int Format;
  u_int* Data;
  u_int NFrames;
  nglTexture** Frames;
};

enum { NGLTEX_IFL = 2 };

extern bool nglInLoadTextureIFL;
extern void nglWarning(const char*, ...);
extern nglTexture* nglLoadTextureA(const char*);
extern void* nglMemAlloc(u_int, u_int = 1);
extern int isspace(int);
extern char* strncpy(char*, const char*, u_int);
extern char* strchr(const char*, int);
extern void* memcpy(void*, const void*, u_int);

bool nglLoadTextureIFL( nglTexture* Tex, unsigned char *Buf, u_int BufSize )
{
  // Temporary buffer for building the texture array.
  static char FileName[256];
  static nglTexture* Textures[512];
  int NTextures = 0;

  if ( nglInLoadTextureIFL )
  {
    nglWarning( "NGL: Recursive IFL detected.\n" );
    return false;
  }
  nglInLoadTextureIFL = true;

// handy parser macro
#define endofbuf( a ) ( (a) - (char*)Buf >= (int)BufSize )

  char* Pos = (char*)Buf;
  while ( !endofbuf( Pos ) )
  {
    // parse out the filename (no extension).
    char* Line = Pos;
    while ( !endofbuf( Line ) && !isspace( *Line ) ) Line++;
    u_int Count = ( Line - Pos < 255 ? Line - Pos : 255 );
    if ( !Count ) break;
    strncpy( FileName, Pos, Count );
    FileName[Count] = '\0';
    char* Ext = strchr( FileName, '.' );
    if ( Ext ) *Ext = '\0';

    if ( (u_int)NTextures >= (sizeof(Textures) / sizeof(Textures[0])) )
    {
      nglWarning( "Exceeded max number of textures in an IFL file (%d).\n", (sizeof(Textures) / sizeof(Textures[0])) );
      break;
    }

    // attempt to load the texture.
    Textures[NTextures] = nglLoadTextureA( FileName );
    if ( Textures[NTextures] )
      NTextures++;

    // skip any whitespace
    Pos = Line;
    while ( !endofbuf( Pos ) && isspace( *Pos ) ) Pos++;
  }

#undef endofbuf

  nglInLoadTextureIFL = false;

  if ( NTextures )
  {
    Tex->Type = NGLTEX_IFL;
    Tex->NFrames = NTextures;

    Tex->Frames = (nglTexture**)nglMemAlloc( sizeof(nglTexture*) * NTextures );
    memcpy( Tex->Frames, Textures, sizeof(nglTexture*) * NTextures );

    // Steal our 'width and height' from the first frame.
    Tex->Width = Tex->Frames[0]->Width;
    Tex->Height = Tex->Frames[0]->Height;
    return true;
  }

  return false;
}
